  "procedures": [
    {
      "procedure_name": {
        "text": "Implement high‑income boolean check",
        "refs": ["Q0000", "Q0001", "Q0002", "Q0003", "Q0004"]
      },
      "steps": [
        {
          "text": "Declare the boolean variable before the code block, e.g., `boolean hasHighIncome;`.",
          "refs": ["Q0000", "Q0001"]
        },
        {
          "text": "Assign the variable based on the income condition using a direct boolean expression: `hasHighIncome = income > 100000;`.",
          "refs": ["Q0003", "Q0004"]
        },
        {
          "text": "Optionally, wrap the expression in parentheses for clarity: `hasHighIncome = (income > 100000);`.",
          "refs": ["Q0004"]
        }
